package glitch

import data.glitch_lib

# Insecure protocol patterns
insecure_protocol_prefixes := ["http://", "ftp://", "telnet://", "smtp://"]

# Cleartext ports
cleartext_ports := {"80", "21", "23", "25", "110", "143", "389", "8021", "8080"}

# Security-related attribute name patterns
security_boolean_attrs := {
    "validate_certs",
    "enforce_https",
    "ssl_required",
    "tls_required",
    "require_secure_transport",
    "verify_peer",
    "cert_validation",
    "encrypt",
    "tls",
    "ssl",
    "secure",
    "use_tls",
    "use_ssl",
    "sslmode",
    "insecure_skip_verify",
    "verify_ssl"
}

# Insecure string values representing false/disabled
insecure_false_strings := {"no", "off", "disabled", "false"}
insecure_true_strings := {"yes", "on", "enabled", "true"}

# Check if value is effectively false (bool false or string "no"/"off"/"disabled"/"false")
is_effectively_false(value) {
    value.ir_type == "Boolean"
    value.value == false
} else {
    value.ir_type == "String"
    lower_val := lower(value.value)
    insecure_false_strings[lower_val]
}

# Check if value is effectively true (bool true or string "yes"/"on"/"enabled"/"true")
is_effectively_true(value) {
    value.ir_type == "Boolean"
    value.value == true
} else {
    value.ir_type == "String"
    lower_val := lower(value.value)
    insecure_true_strings[lower_val]
}

# Check if string value starts with insecure protocol
string_has_insecure_protocol(str) {
    lower_str := lower(str)
    prefix := insecure_protocol_prefixes[_]
    startswith(lower_str, prefix)
}

# Collect all nodes from a Sum tree into a set
collect_sum_nodes(node, nodes) {
    node.ir_type == "String"
    nodes := {node}
} else {
    node.ir_type == "Sum"
    left_nodes := collect_sum_nodes(node.left, _)
    right_nodes := collect_sum_nodes(node.right, _)
    nodes := left_nodes | right_nodes | {node}
} else {
    nodes := {node}
}

# Check if any node in Sum contains insecure protocol
sum_contains_insecure_protocol(node) {
    node.ir_type == "Sum"
    some n in collect_sum_nodes(node, _)
    n.ir_type == "String"
    string_has_insecure_protocol(n.value)
}

# Check node for insecure protocol (non-recursive)
node_contains_insecure_protocol(node) {
    node.ir_type == "String"
    string_has_insecure_protocol(node.value)
} else {
    node.ir_type == "Sum"
    sum_contains_insecure_protocol(node)
}

# Check for insecure protocol value in hash
hash_has_insecure_protocol(hash) {
    [_, entry] := hash.value[_]
    entry.key.ir_type == "String"
    lower(entry.key.value) == "protocol"
    node_contains_insecure_protocol(entry.value)
}

# Check for disabled security in hash (e.g., validate_certs: no)
hash_has_disabled_security(hash) {
    [_, entry] := hash.value[_]
    entry.key.ir_type == "String"
    name := lower(entry.key.value)
    security_boolean_attrs[name]
    is_effectively_false(entry.value)
}

# Check attribute name is security-related boolean
is_security_boolean_attr(name) {
    lower_name := lower(name)
    attr := security_boolean_attrs[_]
    contains(lower_name, attr)
}

# Check cleartext port
is_cleartext_port_value(value) {
    value.ir_type == "String"
    cleartext_ports[value.value]
} else {
    value.ir_type == "Integer"
    port_str := sprintf("%d", [value.value])
    cleartext_ports[port_str]
}

# Check name suggests port configuration
is_port_attr(name) {
    lower_name := lower(name)
    contains(lower_name, "port")
}

# Main detection: disabled security flags
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
